from types import SimpleNamespace as _NS


def _response(stop_reason, *blocks):
    return _NS(stop_reason=stop_reason, content=list(blocks))


_THINK = _NS(type="thinking", thinking="")
_TEXT = _NS(type="text", text='{"theme": "Price", "confidence": 0.9}')

tests.code:
for reason in ["max_tokens", "refusal"]:
    try:
        reply_text(_response(reason, _TEXT))
    except RuntimeError as err:
        assert reason in str(err), str(err)
    else:
        raise AssertionError(f"no RuntimeError for stop_reason={reason}")

try:
    reply_text(_response("end_turn", _THINK))
except RuntimeError:
    pass
else:
    raise AssertionError("no RuntimeError when there is no text block")

